:root {
  --ink: #06060d;
  --cyan: #3df2ff;
  --pink: #ff3d8b;
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: var(--ink);
}

body {
  overscroll-behavior: none;
  touch-action: none;
  -webkit-tap-highlight-color: transparent;
  -webkit-touch-callout: none;
  user-select: none;
  font-family: ui-monospace, "Cascadia Mono", "Courier New", monospace;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 45%, #0b1026 0%, #06060d 62%, #030308 100%);
}

#game {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  cursor: crosshair;
  touch-action: none;
}

.vignette,
.scanlines {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.vignette {
  background: radial-gradient(ellipse at center, transparent 48%, rgba(0, 0, 0, 0.56) 100%);
}

.scanlines {
  opacity: 0.5;
  background: repeating-linear-gradient(
    to bottom,
    rgba(0, 0, 0, 0.16) 0px,
    rgba(0, 0, 0, 0.16) 1px,
    transparent 1px,
    transparent 3px
  );
  mix-blend-mode: multiply;
}

@media (prefers-reduced-motion: reduce) {
  .scanlines {
    display: none;
  }
}

// Hand-authored pixel sprites, rendered once into offscreen canvases.
const DEFS = {
  player: {
    palette: { C: '#3df2ff', W: '#f4feff', D: '#12647c', K: '#06222d' },
    rows: [
      '...CCC...',
      '..CCCCC..',
      '..CWWWC..',
      '..CWWWC..',
      '.CCCCCCC.',
      'CC.CCC.CC',
      '...CCC...',
      '..CC.CC..',
      '.CC...CC.',
    ],
  },
  grunt: {
    palette: { R: '#ff3b57', W: '#ffe9ec', D: '#8c1024', K: '#3d0710' },
    rows: [
      '..RRRR..',
      '.RRRRRR.',
      'RR.WW.RR',
      'RR.RR.RR',
      'RRRRRRRR',
      '.RRRRRR.',
      '.R.RR.R.',
      'DR...RRD',
    ],
  },
  hulk: {
    palette: { H: '#ff9b2f', W: '#fff3d6', D: '#9c4a09', K: '#3d1c02' },
    rows: [
      '....HHHH....',
      '...HHHHHH...',
      '..HHWHHHWHH.',
      '.HHHHHHHHHH.',
      'DHHHHHHHHHHD',
      'HHHHHHHHHHHH',
      'HH.HHHHHH.HH',
      '.HHHHHHHHHH.',
      '..HH.HH.HH..',
      '..H..H..H...',
      '.DH...H...HD',
    ],
  },
  spheroid: {
    palette: { P: '#b45cff', W: '#f4dcff', D: '#5a1a91', K: '#210738' },
    rows: [
      '...PPPP...',
      '..PPPPPP..',
      '.PPDWWDPP.',
      '.PPWWWWPP.',
      'PPDWWWWDPP',
      'PPDWWWWDPP',
      '.PPWWWWPP.',
      '.PPDWWDPP.',
      '..PPPPPP..',
      '...PPPP...',
    ],
  },
  brain: {
    palette: { B: '#ff5fd2', W: '#ffe3f8', D: '#8f166f', K: '#390428' },
    rows: [
      '...BBBB...',
      '..BBBBBB..',
      '.BWBBBBWB.',
      '.BBWBBWBB.',
      'BBBBBBBBBB',
      '.BBBBBBBB.',
      '..BBBBBB..',
      '..B.BB.B..',
      '.B..BB..B.',
    ],
  },
  human: {
    palette: { W: '#eef6ff', Y: '#ffd23f', B: '#7cc6ff', K: '#5b4a12' },
    rows: [
      '..W..',
      '..W..',
      '.YYY.',
      '.YWY.',
      '..Y..',
      '..Y..',
      '..Y..',
      '.B.B.',
    ],
  },
  boss: {
    palette: { M: '#ff2f6d', W: '#fff0f5', D: '#7c0a2e', K: '#2b0210', Y: '#ffd23f' },
    rows: [
      '.....MMMMMM.....',
      '...MMMMMMMMMM...',
      '..MMWWMMMMWWMM..',
      '.MMMWWMMMMWWMMM.',
      '.MMMMMMYYMMMMMM.',
      'MMMMMMYWWYMMMMMM',
      'MMMMMMYYYYMMMMMM',
      'MMMMMMYWWYMMMMMM',
      'MMMMMMMYYMMMMMMM',
      '.MMMMMMMMMMMMMMMM.',
      '..MMMMMMMMMMMMMM..',
      '...MM.MM.MM.MM...',
      '..MM..MM..MM..MM.',
      '.M...MM....MM...M',
      '....M........M...',
    ],
  },
};

function normalizeRows(rows) {
  const width = Math.max(...rows.map((r) => r.length));
  return rows.map((r) => r.padEnd(width, '.'));
}

function makeCanvas(rows, palette, override) {
  const width = rows[0].length;
  const height = rows.length;
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const ch = rows[y][x];
      if (ch === '.' || ch === ' ') continue;
      const color = override || palette[ch];
      if (!color) continue;
      ctx.fillStyle = color;
      ctx.fillRect(x, y, 1, 1);
    }
  }
  return canvas;
}

const SPRITES = {};

function build() {
  for (const [name, def] of Object.entries(DEFS)) {
    const rows = normalizeRows(def.rows);
    SPRITES[name] = {
      normal: makeCanvas(rows, def.palette),
      flash: makeCanvas(rows, def.palette, '#ffffff'),
      width: rows[0].length,
      height: rows.length,
    };
  }
}

build();

export function spriteSize(name) {
  return { width: SPRITES[name].width, height: SPRITES[name].height };
}

export function drawSprite(ctx, name, cx, cy, art = 1, flash = false, alpha = 1) {
  const sprite = SPRITES[name];
  if (!sprite) return;
  const image = flash ? sprite.flash : sprite.normal;
  const w = image.width * art;
  const h = image.height * art;
  const x = Math.round(cx - w / 2);
  const y = Math.round(cy - h / 2);
  const prevAlpha = ctx.globalAlpha;
  ctx.globalAlpha = prevAlpha * alpha;
  ctx.drawImage(image, x, y, Math.max(1, Math.round(w)), Math.max(1, Math.round(h)));
  ctx.globalAlpha = prevAlpha;
}

// A tiny human icon for the HUD, drawn without touching the global transform.
export function drawHumanIcon(ctx, x, y, scale = 1, color = null) {
  const sprite = SPRITES.human;
  const image = color ? makeTinted(sprite.normal, color) : sprite.normal;
  ctx.drawImage(image, Math.round(x), Math.round(y), image.width * scale, image.height * scale);
}

const tintCache = new Map();
function makeTinted(source, color) {
  const key = color;
  if (tintCache.has(key)) return tintCache.get(key);
  const canvas = document.createElement('canvas');
  canvas.width = source.width;
  canvas.height = source.height;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(source, 0, 0);
  ctx.globalCompositeOperation = 'source-in';
  ctx.fillStyle = color;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  tintCache.set(key, canvas);
  return canvas;
}

// Tiny procedural sound engine. No assets, no network, all synthesized.
const MUTE_KEY = 'neon-rampage-muted';

export class Sfx {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.noiseBuffer = null;
    this.lastHit = 0;
    this.muted = false;
    try {
      this.muted = localStorage.getItem(MUTE_KEY) === '1';
    } catch {
      this.muted = false;
    }
  }

  ensure() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.24;
    this.master.connect(this.ctx.destination);
    this.noiseBuffer = this.makeNoise();
  }

  makeNoise() {
    const length = Math.floor(this.ctx.sampleRate * 0.6);
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1;
    return buffer;
  }

  get on() {
    return !this.muted && !!this.ctx;
  }

  setMuted(value) {
    this.muted = !!value;
    try {
      localStorage.setItem(MUTE_KEY, this.muted ? '1' : '0');
    } catch {}
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(this.muted ? 0 : 0.24, this.ctx.currentTime, 0.02);
    }
    if (!this.muted) this.ui();
  }

  toggle() {
    this.setMuted(!this.muted);
    return this.muted;
  }

  tone(f0, f1, dur, type = 'square', vol = 0.15, delay = 0) {
    if (!this.on) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, f0), t);
    if (f1 !== f0) osc.frequency.exponentialRampToValueAtTime(Math.max(20, f1), t + dur);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t + Math.min(0.012, dur * 0.2));
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.03);
  }

  noise(dur, vol, cutoff = 900, delay = 0) {
    if (!this.on) return;
    const t = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(cutoff, t);
    filter.frequency.exponentialRampToValueAtTime(Math.max(80, cutoff * 0.18), t + dur);
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(vol, t);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    src.start(t);
    src.stop(t + dur + 0.02);
  }

  shoot() {
    this.tone(920 + Math.random() * 80, 320, 0.06, 'square', 0.06);
  }

  hit() {
    const now = performance.now();
    if (now - this.lastHit < 40) return;
    this.lastHit = now;
    this.tone(240, 110, 0.045, 'square', 0.055);
  }

  explode() {
    this.noise(0.22, 0.17, 1500);
    this.tone(160, 42, 0.2, 'sawtooth', 0.08);
  }

  bigExplode() {
    this.noise(0.55, 0.26, 2200);
    this.tone(120, 30, 0.55, 'sawtooth', 0.14);
  }

  rescue() {
    this.tone(523, 523, 0.08, 'triangle', 0.12);
    this.tone(784, 784, 0.08, 'triangle', 0.12, 0.075);
    this.tone(1046, 1046, 0.12, 'triangle', 0.12, 0.15);
  }

  death() {
    this.tone(440, 70, 0.6, 'sawtooth', 0.14);
    this.noise(0.45, 0.2, 1200);
  }

  wave() {
    this.tone(330, 330, 0.09, 'square', 0.09);
    this.tone(440, 440, 0.09, 'square', 0.09, 0.1);
    this.tone(660, 660, 0.16, 'square', 0.1, 0.2);
  }

  extra() {
    this.tone(880, 880, 0.07, 'triangle', 0.13);
    this.tone(1174, 1174, 0.07, 'triangle', 0.13, 0.07);
    this.tone(1568, 1568, 0.16, 'triangle', 0.13, 0.14);
  }

  gameOver() {
    this.tone(330, 330, 0.18, 'square', 0.1);
    this.tone(262, 262, 0.18, 'square', 0.1, 0.2);
    this.tone(196, 196, 0.22, 'square', 0.1, 0.4);
    this.tone(131, 60, 0.7, 'sawtooth', 0.12, 0.65);
  }

  ui() {
    this.tone(660, 660, 0.04, 'square', 0.06);
  }
}

// Unified keyboard / mouse / touch / gamepad input.
//
// Touch layout: left side of the screen is a movement stick, right side is an
// aim + fire stick. Both are dynamic, so they appear wherever the thumb lands.

const MOVE_KEYS = new Set(['KeyW', 'KeyA', 'KeyS', 'KeyD']);
const AIM_KEYS = new Set(['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight']);

export class Input {
  constructor(canvas) {
    this.canvas = canvas;
    this.view = { w: 480, h: 300 };
    this.keys = new Set();
    this.actions = [];
    this.enabled = false;
    this.coarse = false;
    this.onUiTap = null;

    this.mouse = { x: 0, y: 0, active: false, down: false };
    this.sticks = { move: null, aim: null };
    this.pointerSide = new Map();

    this.move = { x: 0, y: 0 };
    this.aimDir = null;
    this.firing = false;
    this.padStart = false;

    this.moveVec = { x: 0, y: 0 };
    this.aimVec = { x: 0, y: 0 };

    try {
      this.coarse = window.matchMedia('(pointer: coarse)').matches;
    } catch {}

    this.onDown = this.onDown.bind(this);
    this.onMove = this.onMove.bind(this);
    this.onUp = this.onUp.bind(this);
    this.onKeyDown = this.onKeyDown.bind(this);
    this.onKeyUp = this.onKeyUp.bind(this);
    this.onBlur = this.onBlur.bind(this);
  }

  attach() {
    const c = this.canvas;
    c.addEventListener('pointerdown', this.onDown, { passive: false });
    c.addEventListener('pointermove', this.onMove, { passive: false });
    c.addEventListener('pointerup', this.onUp);
    c.addEventListener('pointercancel', this.onUp);
    c.addEventListener('contextmenu', (e) => e.preventDefault());
    window.addEventListener('keydown', this.onKeyDown);
    window.addEventListener('keyup', this.onKeyUp);
    window.addEventListener('blur', this.onBlur);
  }

  setView(view) {
    this.view = view;
  }

  setEnabled(value) {
    this.enabled = !!value;
    if (!this.enabled) {
      this.sticks.move = null;
      this.sticks.aim = null;
      this.mouse.down = false;
    }
  }

  rect() {
    return this.canvas.getBoundingClientRect();
  }

  toWorld(clientX, clientY) {
    const r = this.rect();
    return {
      x: ((clientX - r.left) / Math.max(1, r.width)) * this.view.w,
      y: ((clientY - r.top) / Math.max(1, r.height)) * this.view.h,
    };
  }

  stickRadius() {
    const base = Math.min(this.view.w, this.view.h);
    return Math.max(15, Math.min(28, base * 0.11));
  }

  onDown(e) {
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    e.preventDefault();
    const p = this.toWorld(e.clientX, e.clientY);

    if (e.pointerType === 'mouse') {
      this.mouse.x = p.x;
      this.mouse.y = p.y;
      this.mouse.active = true;
    }

    if (this.onUiTap && this.onUiTap(p.x, p.y, e.pointerType)) return;
    if (!this.enabled) return;

    if (e.pointerType === 'mouse') {
      this.mouse.down = true;
      return;
    }

    const r = this.rect();
    const left = e.clientX < r.left + r.width / 2;
    let side = left ? 'move' : 'aim';
    if (this.sticks[side]) side = side === 'move' ? 'aim' : 'move';
    if (this.sticks[side]) return;

    const stick = {
      id: e.pointerId,
      side,
      baseX: p.x,
      baseY: p.y,
      knobX: p.x,
      knobY: p.y,
      dx: 0,
      dy: 0,
      mag: 0,
    };
    this.sticks[side] = stick;
    this.pointerSide.set(e.pointerId, side);
    this.coarse = true;
    try {
      this.canvas.setPointerCapture(e.pointerId);
    } catch {}
  }

  onMove(e) {
    if (e.pointerType === 'mouse') {
      const p = this.toWorld(e.clientX, e.clientY);
      this.mouse.x = p.x;
      this.mouse.y = p.y;
      this.mouse.active = true;
      return;
    }
    const side = this.pointerSide.get(e.pointerId);
    if (!side) return;
    const stick = this.sticks[side];
    if (!stick) return;
    e.preventDefault();
    const p = this.toWorld(e.clientX, e.clientY);
    const radius = this.stickRadius();
    let dx = p.x - stick.baseX;
    let dy = p.y - stick.baseY;
    const dist = Math.hypot(dx, dy);
    if (dist > radius) {
      dx = (dx / dist) * radius;
      dy = (dy / dist) * radius;
    }
    stick.dx = dx / radius;
    stick.dy = dy / radius;
    stick.mag = Math.min(1, dist / radius);
    stick.knobX = stick.baseX + dx;
    stick.knobY = stick.baseY + dy;
  }

  onUp(e) {
    if (e.pointerType === 'mouse') {
      this.mouse.down = false;
      return;
    }
    const side = this.pointerSide.get(e.pointerId);
    if (side) {
      this.sticks[side] = null;
      this.pointerSide.delete(e.pointerId);
    }
    try {
      this.canvas.releasePointerCapture(e.pointerId);
    } catch {}
  }

  onKeyDown(e) {
    if (e.repeat) return;
    const code = e.code;
    if (MOVE_KEYS.has(code) || AIM_KEYS.has(code) || code === 'Space') {
      e.preventDefault();
    }
    this.keys.add(code);
    if (code === 'Enter') this.actions.push('start');
    else if (code === 'Escape' || code === 'KeyP') this.actions.push('pause');
    else if (code === 'KeyM') this.actions.push('mute');
    else if (code === 'KeyR') this.actions.push('restart');
  }

  onKeyUp(e) {
    this.keys.delete(e.code);
  }

  onBlur() {
    this.keys.clear();
    this.mouse.down = false;
    this.sticks.move = null;
    this.sticks.aim = null;
    this.pointerSide.clear();
  }

  pollGamepad() {
    if (!navigator.getGamepads) return null;
    const pads = navigator.getGamepads();
    for (const pad of pads) {
      if (pad && pad.connected) return pad;
    }
    return null;
  }

  update() {
    let mx = 0;
    let my = 0;
    let aim = null;
    let firing = false;

    // ----- movement -----
    const moveStick = this.sticks.move;
    if (moveStick && moveStick.mag > 0.12) {
      mx = moveStick.dx;
      my = moveStick.dy;
      const m = Math.hypot(mx, my);
      if (m > 1) {
        mx /= m;
        my /= m;
      }
    } else {
      if (this.keys.has('KeyA')) mx -= 1;
      if (this.keys.has('KeyD')) mx += 1;
      if (this.keys.has('KeyW')) my -= 1;
      if (this.keys.has('KeyS')) my += 1;
      const m = Math.hypot(mx, my);
      if (m > 1) {
        mx /= m;
        my /= m;
      }
    }

    // ----- aim -----
    const aimStick = this.sticks.aim;
    if (aimStick && aimStick.mag > 0.16) {
      const m = Math.hypot(aimStick.dx, aimStick.dy) || 1;
      aim = { x: aimStick.dx / m, y: aimStick.dy / m };
      firing = aimStick.mag > 0.26;
    } else {
      let ax = 0;
      let ay = 0;
      if (this.keys.has('ArrowLeft')) ax -= 1;
      if (this.keys.has('ArrowRight')) ax += 1;
      if (this.keys.has('ArrowUp')) ay -= 1;
      if (this.keys.has('ArrowDown')) ay += 1;
      if (ax || ay) {
        const m = Math.hypot(ax, ay);
        aim = { x: ax / m, y: ay / m };
        firing = true;
      }
    }

    // ----- gamepad -----
    const pad = this.pollGamepad();
    if (pad) {
      const lx = pad.axes[0] || 0;
      const ly = pad.axes[1] || 0;
      const lm = Math.hypot(lx, ly);
      if (!moveStick && lm > 0.22 && !this.keys.has('KeyA') && !this.keys.has('KeyD') && !this.keys.has('KeyW') && !this.keys.has('KeyS')) {
        const scale = Math.min(1, (lm - 0.18) / 0.7);
        mx = (lx / lm) * scale;
        my = (ly / lm) * scale;
      }
      const rx = pad.axes[2] || 0;
      const ry = pad.axes[3] || 0;
      const rm = Math.hypot(rx, ry);
      if (!aim && rm > 0.32) {
        aim = { x: rx / rm, y: ry / rm };
        firing = true;
      }
      if ((pad.buttons[7] && pad.buttons[7].value > 0.35) || (pad.buttons[6] && pad.buttons[6].value > 0.35)) {
        firing = true;
      }
      const start = !!(pad.buttons[9] && pad.buttons[9].pressed);
      const face = !!(pad.buttons[0] && pad.buttons[0].pressed);
      if ((start && !this.padStart) || (face && !this.enabled)) this.actions.push('start');
      this.padStart = start || face;
    } else {
      this.padStart = false;
    }

    if (this.keys.has('Space')) firing = true;

    this.move.x = mx;
    this.move.y = my;
    this.aimDir = aim;
    this.firing = firing;

    if (mx || my) {
      const m = Math.hypot(mx, my) || 1;
      this.moveVec.x = mx / m;
      this.moveVec.y = my / m;
    } else {
      this.moveVec.x = 0;
      this.moveVec.y = 0;
    }
    if (aim) {
      this.aimVec.x = aim.x;
      this.aimVec.y = aim.y;
    }
  }
}

import { renderGame } from './render.js';

const PAD = (n, width = 2) => String(Math.max(0, Math.floor(n))).padStart(width, '0');
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const rand = (a, b) => a + Math.random() * (b - a);
const dist = (ax, ay, bx, by) => Math.hypot(ax - bx, ay - by);

const PLAYER_SPEED = 86;
const BULLET_SPEED = 265;
const FIRE_INTERVAL = 0.095;
const HIGH_KEY = 'neon-rampage-high';

const ENEMIES = {
  grunt: { r: 3.8, hp: 1, speed: 36, score: 100, color: '#ff3b57' },
  hulk: { r: 5.8, hp: 6, speed: 19, score: 500, color: '#ff9b2f' },
  spheroid: { r: 4.8, hp: 4, speed: 23, score: 300, color: '#b45cff' },
  brain: { r: 3.9, hp: 2, speed: 44, score: 300, color: '#ff5fd2' },
};

function makeRng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

export class Game {
  constructor(canvas, input, sfx) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.ctx.imageSmoothingEnabled = false;
    this.input = input;
    this.sfx = sfx;
    this.view = { w: 480, h: 300, scale: 3, art: 1 };
    this.state = 'title';
    this.time = 0;
    this.shake = 0;
    this.high = 0;
    this.newHigh = false;
    try {
      this.high = Number(localStorage.getItem(HIGH_KEY)) || 0;
    } catch {}

    this.score = 0;
    this.lives = 3;
    this.wave = 0;
    this.kills = 0;
    this.rescued = 0;
    this.rescuedThisWave = 0;
    this.nextLife = 15000;
    this.waveState = 'idle';
    this.waveTimer = 0;
    this.pending = [];
    this.spawnTimer = 0;
    this.banner = null;

    this.player = this.makePlayer();
    this.bullets = [];
    this.enemies = [];
    this.humans = [];
    this.particles = [];
    this.texts = [];
    this.ambient = [];
    this.stars = [];

    this.makeAmbient();
    this.makeStars();
  }

  makePlayer() {
    return {
      x: this.view.w / 2,
      y: this.view.h / 2,
      r: 3.4,
      aimX: 1,
      aimY: 0,
      dead: false,
      respawnT: 0,
      invuln: 0,
      fireCd: 0,
      muzzle: 0,
    };
  }

  makeStars() {
    const rng = makeRng(90210);
    const count = Math.round((this.view.w * this.view.h) / 5200);
    this.stars = [];
    for (let i = 0; i < count; i++) {
      this.stars.push({
        x: Math.floor(rng() * this.view.w),
        y: Math.floor(rng() * this.view.h),
        a: 0.1 + rng() * 0.28,
        c: rng() < 0.22 ? '#ff3d8b' : '#3df2ff',
      });
    }
  }

  makeAmbient() {
    const types = ['grunt', 'grunt', 'grunt', 'hulk', 'spheroid', 'brain', 'human', 'human'];
    const count = clamp(Math.round((this.view.w * this.view.h) / 14000), 7, 18);
    this.ambient = [];
    for (let i = 0; i < count; i++) {
      this.ambient.push({
        type: types[Math.floor(Math.random() * types.length)],
        x: rand(12, this.view.w - 12),
        y: rand(12, this.view.h - 12),
        vx: rand(-9, 9),
        vy: rand(-7, 7),
        phase: rand(0, Math.PI * 2),
      });
    }
  }

  setView(view) {
    const old = this.view;
    this.view = view;
    if (this.input) this.input.setView(view);
    const w = view.w;
    const h = view.h;
    if (old.w !== w || old.h !== h) {
      this.makeStars();
      if (this.state === 'title') this.makeAmbient();
    }
    const px = clamp(this.player.x, 8, w - 8);
    const py = clamp(this.player.y, 8, h - 8);
    this.player.x = px;
    this.player.y = py;
    for (const e of this.enemies) {
      e.x = clamp(e.x, 8, w - 8);
      e.y = clamp(e.y, 8, h - 8);
    }
    for (const b of this.bullets) {
      b.x = clamp(b.x, 0, w);
      b.y = clamp(b.y, 0, h);
    }
    for (const hm of this.humans) {
      hm.x = clamp(hm.x, 10, w - 10);
      hm.y = clamp(hm.y, 10, h - 10);
    }
    for (const p of this.particles) {
      p.x = clamp(p.x, 0, w);
      p.y = clamp(p.y, 0, h);
    }
    for (const a of this.ambient) {
      a.x = clamp(a.x, 8, w - 8);
      a.y = clamp(a.y, 8, h - 8);
    }
  }

  syncInput() {
    if (!this.input) return;
    this.input.setEnabled(this.state === 'playing');
  }

  // ---------- state ----------

  startRun() {
    this.sfx.ensure();
    this.state = 'playing';
    this.time = 0;
    this.shake = 0;
    this.score = 0;
    this.lives = 3;
    this.wave = 0;
    this.kills = 0;
    this.rescued = 0;
    this.rescuedThisWave = 0;
    this.nextLife = 15000;
    this.newHigh = false;
    this.waveState = 'idle';
    this.waveTimer = 0;
    this.pending = [];
    this.spawnTimer = 0;
    this.banner = null;
    this.bullets = [];
    this.enemies = [];
    this.humans = [];
    this.particles = [];
    this.texts = [];
    this.player = this.makePlayer();
    this.player.invuln = 1.4;
    this.syncInput();
    this.startWave();
  }

  startWave() {
    this.wave += 1;
    this.waveState = 'fight';
    this.waveTimer = 0;
    this.pending = this.buildWave(this.wave);
    this.spawnTimer = 1.0;
    this.spawnInterval = Math.max(0.26, 0.56 - this.wave * 0.012);
    this.maxAlive = Math.max(11, Math.round(Math.min(30, 17 + this.wave) * this.density()));
    this.rescuedThisWave = 0;
    this.enemies = [];
    this.bullets = [];
    this.humans = [];
    for (const h of this.spawnHumans()) this.humans.push(h);
    this.banner = {
      title: `WAVE ${PAD(this.wave)}`,
      sub: this.wave === 1 ? 'RESCUE THE CIVILIANS' : `${this.pending.length} HOSTILES INBOUND`,
      t: 0,
      life: 1.7,
      color: '#3df2ff',
    };
    this.sfx.wave();
  }

  density() {
    return clamp(Math.sqrt((this.view.w * this.view.h) / 144000), 0.68, 1.1);
  }

  buildWave(n) {
    const d = this.density();
    const list = [];
    const grunts = Math.max(6, Math.round((8 + n * 2) * d));
    const hulks = n >= 2 ? clamp(Math.round((1 + Math.floor((n - 2) / 2)) * d), 1, 6) : 0;
    const spheroids = n >= 3 ? clamp(Math.round((1 + Math.floor((n - 3) / 4)) * Math.min(1, d + 0.2)), 1, 4) : 0;
    const brains = n >= 4 ? clamp(Math.round((1 + Math.floor((n - 4) / 4)) * Math.min(1, d + 0.2)), 1, 4) : 0;
    for (let i = 0; i < grunts; i++) list.push('grunt');
    for (let i = 0; i < hulks; i++) list.push('hulk');
    for (let i = 0; i < spheroids; i++) list.push('spheroid');
    for (let i = 0; i < brains; i++) list.push('brain');
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  }

  spawnHumans() {
    const count = Math.max(3, Math.round(5 * this.density()));
    const out = [];
    const w = this.view.w;
    const h = this.view.h;
    for (let i = 0; i < count; i++) {
      let best = { x: w / 2, y: h / 2 };
      let bestD = -1;
      for (let tries = 0; tries < 18; tries++) {
        const x = rand(16, w - 16);
        const y = rand(34, h - 16);
        const d = dist(x, y, this.player.x, this.player.y);
        if (d > bestD) {
          bestD = d;
          best = { x, y };
        }
        if (d > Math.min(70, Math.min(w, h) * 0.34)) break;
      }
      out.push({
        x: best.x,
        y: best.y,
        r: 2.4,
        dead: false,
        dirX: rand(-1, 1),
        dirY: rand(-1, 1),
        wander: rand(0.5, 2.5),
        seed: rand(0, 10),
      });
    }
    return out;
  }

  pause() {
    if (this.state !== 'playing') return;
    this.state = 'paused';
    this.syncInput();
    this.sfx.ui();
  }

  resume() {
    if (this.state !== 'paused') return;
    this.state = 'playing';
    this.syncInput();
    this.sfx.ui();
  }

  endRun() {
    if (this.state === 'gameover') return;
    this.newHigh = this.score > this.high;
    this.high = Math.max(this.high, this.score);
    try {
      localStorage.setItem(HIGH_KEY, String(this.high));
    } catch {}
    this.state = 'gameover';
    this.syncInput();
    this.shake = 5;
    this.sfx.gameOver();
  }

  handleAction(action) {
    if (action === 'mute') {
      this.sfx.ensure();
      this.sfx.toggle();
      return;
    }
    if (action === 'pause') {
      if (this.state === 'playing') this.pause();
      else if (this.state === 'paused') this.resume();
      return;
    }
    if (action === 'restart') {
      if (this.state === 'gameover') this.startRun();
      return;
    }
    if (action === 'start') {
      if (this.state === 'title' || this.state === 'gameover') this.startRun();
      else if (this.state === 'playing') this.pause();
      else if (this.state === 'paused') this.resume();
    }
  }

  uiButtons() {
    const list = [];
    const w = this.view.w;
    const h = this.view.h;
    if (this.state === 'playing' || this.state === 'paused') {
      const small = w < 320;
      const y = small ? 23 : 20;
      list.push({ id: 'mute', x: w - 38, y, w: 14, h: 14 });
      list.push({ id: 'pause', x: w - 20, y, w: 14, h: 14 });
    } else if (this.state === 'title' || this.state === 'gameover') {
      list.push({ id: 'mute', x: w - 20, y: h - 20, w: 14, h: 14 });
    }
    return list;
  }

  handleUiTap(x, y) {
    for (const b of this.uiButtons()) {
      if (x >= b.x - 4 && x <= b.x + b.w + 4 && y >= b.y - 4 && y <= b.y + b.h + 4) {
        if (b.id === 'pause') {
          if (this.state === 'paused') this.resume();
          else this.pause();
        } else if (b.id === 'mute') {
          this.sfx.ensure();
          this.sfx.toggle();
        }
        return true;
      }
    }
    if (this.state === 'title' || this.state === 'gameover') {
      this.startRun();
      return true;
    }
    if (this.state === 'paused') {
      this.resume();
      return true;
    }
    return false;
  }

  // ---------- update ----------

  update(dt) {
    this.time += dt;
    this.shake = Math.max(0, this.shake - dt * 30);
    if (this.input) {
      for (const action of this.input.actions.splice(0)) this.handleAction(action);
    }
    if (this.state === 'title') {
      this.updateAmbient(dt);
      this.updateEffects(dt);
      this.updateBanner(dt);
    } else if (this.state === 'playing') {
      this.updatePlaying(dt);
      this.updateBanner(dt);
    } else if (this.state === 'gameover') {
      this.updateEffects(dt * 0.35);
      this.updateBanner(dt);
    }
  }

  updateBanner(dt) {
    if (!this.banner) return;
    this.banner.t += dt;
    if (this.banner.t > this.banner.life + 0.5) this.banner = null;
  }

  updatePlaying(dt) {
    this.waveTimer += dt;

    if (this.waveState === 'fight') {
      this.spawnTimer -= dt;
      if (this.spawnTimer <= 0 && this.pending.length && this.enemies.length < this.maxAlive) {
        this.spawnEnemy(this.pending.shift());
        this.spawnTimer = this.spawnInterval;
      }
    }

    this.updatePlayer(dt);
    this.updateBullets(dt);
    this.updateEnemies(dt);
    this.updateHumans(dt);
    this.collideBullets();
    this.collidePlayer();
    this.collideHumans();
    this.separateEnemies();
    this.updateEffects(dt);
    this.enemies = this.enemies.filter((e) => !e.dead);
    this.humans = this.humans.filter((h) => !h.dead);

    if (
      this.waveState === 'fight' &&
      this.pending.length === 0 &&
      this.enemies.length === 0
    ) {
      this.clearWave();
    }

    if (this.waveState === 'clear') {
      if (this.waveTimer > 2.3 && !this.player.dead) {
        this.startWave();
      }
    }
  }

  updateAmbient(dt) {
    const w = this.view.w;
    const h = this.view.h;
    for (const a of this.ambient) {
      a.x += a.vx * dt;
      a.y += a.vy * dt;
      if (a.x < 8) {
        a.x = 8;
        a.vx = Math.abs(a.vx);
      }
      if (a.x > w - 8) {
        a.x = w - 8;
        a.vx = -Math.abs(a.vx);
      }
      if (a.y < 8) {
        a.y = 8;
        a.vy = Math.abs(a.vy);
      }
      if (a.y > h - 8) {
        a.y = h - 8;
        a.vy = -Math.abs(a.vy);
      }
      a.phase += dt;
    }
  }

  updateEffects(dt) {
    for (const p of this.particles) {
      p.life -= dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      const drag = Math.max(0, 1 - dt * 2.6);
      p.vx *= drag;
      p.vy *= drag;
    }
    for (const t of this.texts) {
      t.life -= dt;
      t.y -= 15 * dt;
    }
    this.particles = this.particles.filter((p) => p.life > 0);
    this.texts = this.texts.filter((t) => t.life > 0);
  }

  addScore(n) {
    this.score += n;
    while (this.score >= this.nextLife) {
      this.lives = Math.min(9, this.lives + 1);
      this.nextLife += 25000;
      this.showText('EXTRA LIFE', this.player.x, this.player.y - 14, '#7cffb2', 2.4);
      this.sfx.extra();
    }
  }

  showText(text, x, y, color = '#ffffff', life = 0.9) {
    this.texts.push({ text, x, y, color, life, maxLife: life });
  }

  // ---------- player ----------

  updatePlayer(dt) {
    const p = this.player;
    if (p.dead) {
      p.respawnT -= dt;
      if (p.respawnT <= 0) {
        if (this.lives > 0) this.respawn();
        else this.endRun();
      }
      return;
    }

    p.invuln = Math.max(0, p.invuln - dt);
    p.fireCd = Math.max(0, p.fireCd - dt);
    p.muzzle = Math.max(0, p.muzzle - dt);

    const input = this.input;
    const w = this.view.w;
    const h = this.view.h;
    if (input) {
      p.x += input.move.x * PLAYER_SPEED * dt;
      p.y += input.move.y * PLAYER_SPEED * dt;

      let aim = input.aimDir;
      if (!aim && input.mouse.active) {
        const dx = input.mouse.x - p.x;
        const dy = input.mouse.y - p.y;
        const m = Math.hypot(dx, dy);
        if (m > 2) aim = { x: dx / m, y: dy / m };
      }
      if (aim) {
        const m = Math.hypot(aim.x, aim.y) || 1;
        p.aimX = aim.x / m;
        p.aimY = aim.y / m;
      }
      if (input.firing) this.shoot();
    }
    p.x = clamp(p.x, 7, w - 7);
    p.y = clamp(p.y, 8, h - 8);

    for (let i = this.humans.length - 1; i >= 0; i--) {
      const hm = this.humans[i];
      if (dist(p.x, p.y, hm.x, hm.y) < p.r + hm.r + 2.5) {
        this.rescueHuman(hm, 1000);
        this.humans.splice(i, 1);
      }
    }
  }

  shoot() {
    const p = this.player;
    if (p.fireCd > 0 || p.dead) return;
    p.fireCd = FIRE_INTERVAL;
    p.muzzle = 0.055;
    const ax = p.aimX;
    const ay = p.aimY;
    const x = p.x + ax * 5;
    const y = p.y + ay * 5;
    if (this.bullets.length < 80) {
      this.bullets.push({
        x,
        y,
        vx: ax * BULLET_SPEED,
        vy: ay * BULLET_SPEED,
        life: 0.92,
        r: 1.5,
        dead: false,
      });
    }
    this.spawnParticles(x, y, '#aefbff', 2, { speed: 24, life: 0.12, size: 1 });
    this.sfx.shoot();
  }

  respawn() {
    const p = this.player;
    p.dead = false;
    p.x = this.view.w / 2;
    p.y = this.view.h / 2;
    p.invuln = 2.6;
    p.fireCd = 0;
    p.respawnT = 0;
    for (const e of this.enemies) {
      const d = dist(e.x, e.y, p.x, p.y);
      if (d < 58) {
        const m = d || 1;
        e.x = clamp(p.x + ((e.x - p.x) / m) * 64, 8, this.view.w - 8);
        e.y = clamp(p.y + ((e.y - p.y) / m) * 64, 8, this.view.h - 8);
      }
    }
    this.spawnParticles(p.x, p.y, '#3df2ff', 18, { speed: 75, life: 0.6, size: 1 });
  }

  playerDie() {
    const p = this.player;
    if (p.dead || p.invuln > 0) return;
    p.dead = true;
    p.respawnT = 1.35;
    this.lives = Math.max(0, this.lives - 1);
    this.shake = 10;
    this.spawnParticles(p.x, p.y, '#3df2ff', 26, { speed: 105, life: 0.85, size: 2 });
    this.spawnParticles(p.x, p.y, '#ff3d8b', 18, { speed: 70, life: 0.7, size: 1 });
    this.sfx.death();
  }

  respawnBlocked() {}

  // ---------- enemies ----------

  spawnEnemy(type, at) {
    const def = ENEMIES[type];
    const pos = at || this.edgeSpawn();
    let hp = def.hp;
    if (type === 'hulk') hp += Math.floor(this.wave / 4);
    if (type === 'spheroid') hp += Math.floor(this.wave / 7);
    if (type === 'brain') hp += Math.floor(this.wave / 9);
    const speed = def.speed * (1 + Math.min(0.48, this.wave * 0.016));
    const e = {
      type,
      x: pos.x,
      y: pos.y,
      r: def.r,
      hp,
      maxHp: hp,
      speed,
      score: def.score,
      color: def.color,
      spawnT: at ? 0.22 : 0.55,
      hitFlash: 0,
      dead: false,
      seed: rand(0, 100),
      spawnCd: rand(1.6, 2.8),
      spawned: 0,
      wp: null,
    };
    this.enemies.push(e);
    return e;
  }

  edgeSpawn() {
    const w = this.view.w;
    const h = this.view.h;
    const m = 10;
    const minD = Math.min(75, Math.min(w, h) * 0.3);
    let pick = { x: m, y: m };
    let best = -1;
    for (let i = 0; i < 14; i++) {
      const side = Math.floor(Math.random() * 4);
      let x;
      let y;
      if (side === 0) {
        x = rand(m, w - m);
        y = m;
      } else if (side === 1) {
        x = w - m;
        y = rand(m, h - m);
      } else if (side === 2) {
        x = rand(m, w - m);
        y = h - m;
      } else {
        x = m;
        y = rand(m, h - m);
      }
      const d = dist(x, y, this.player.x, this.player.y);
      if (d > best) {
        best = d;
        pick = { x, y };
      }
      if (d > minD) break;
    }
    return pick;
  }

  updateEnemies(dt) {
    const p = this.player;
    for (const e of this.enemies) {
      if (e.dead) continue;
      if (e.spawnT > 0) {
        e.spawnT -= dt;
        if (e.spawnT <= 0) {
          e.spawnT = 0;
          this.spawnParticles(e.x, e.y, e.color, 7, { speed: 45, life: 0.35, size: 1 });
        }
        continue;
      }
      e.hitFlash = Math.max(0, e.hitFlash - dt);
      let tx = p.x;
      let ty = p.y;

      if (e.type === 'brain') {
        let bestD = Infinity;
        for (const hm of this.humans) {
          if (hm.dead) continue;
          const d = dist(e.x, e.y, hm.x, hm.y);
          if (d < bestD) {
            bestD = d;
            tx = hm.x;
            ty = hm.y;
          }
        }
        if (bestD === Infinity) {
          tx = p.x;
          ty = p.y;
        } else if (bestD < e.r + 3) {
          const hm = this.humans.find((x) => x.dead === false && dist(e.x, e.y, x.x, x.y) === bestD);
          if (hm) this.killHuman(hm);
        }
      } else if (e.type === 'spheroid') {
        if (!e.wp || dist(e.x, e.y, e.wp.x, e.wp.y) < 7) {
          e.wp = { x: rand(14, this.view.w - 14), y: rand(22, this.view.h - 14) };
        }
        tx = e.wp.x;
        ty = e.wp.y;
        e.spawnCd -= dt;
        if (e.spawnCd <= 0 && e.spawned < 3) {
          e.spawnCd = 2.5;
          e.spawned++;
          for (let i = 0; i < 2; i++) {
            const ang = rand(0, Math.PI * 2);
            const at = {
              x: clamp(e.x + Math.cos(ang) * 9, 8, this.view.w - 8),
              y: clamp(e.y + Math.sin(ang) * 9, 8, this.view.h - 8),
            };
            const spawned = this.spawnEnemy('grunt', at);
            spawned.speed *= 0.92;
          }
          this.spawnParticles(e.x, e.y, '#b45cff', 6, { speed: 35, life: 0.4, size: 1 });
        }
      }

      let dx = tx - e.x;
      let dy = ty - e.y;
      const d = Math.hypot(dx, dy) || 1;
      dx /= d;
      dy /= d;

      if (e.type === 'grunt') {
        const wob = Math.sin(this.time * 7 + e.seed) * 0.38;
        const nx = -dy;
        const ny = dx;
        e.x += (dx + nx * wob) * e.speed * dt;
        e.y += (dy + ny * wob) * e.speed * dt;
      } else if (e.type === 'brain') {
        const boost = this.humans.length === 0 ? 1.22 : 1;
        e.x += dx * e.speed * boost * dt;
        e.y += dy * e.speed * boost * dt;
      } else {
        e.x += dx * e.speed * dt;
        e.y += dy * e.speed * dt;
      }

      e.x = clamp(e.x, e.r + 4, this.view.w - e.r - 4);
      e.y = clamp(e.y, e.r + 4, this.view.h - e.r - 4);
    }
    this.enemies = this.enemies.filter((e) => !e.dead);
  }

  separateEnemies() {
    const arr = this.enemies;
    for (let i = 0; i < arr.length; i++) {
      const a = arr[i];
      if (a.spawnT > 0 || a.dead) continue;
      for (let j = i + 1; j < arr.length; j++) {
        const b = arr[j];
        if (b.spawnT > 0 || b.dead) continue;
        let dx = b.x - a.x;
        let dy = b.y - a.y;
        const d = Math.hypot(dx, dy);
        const min = a.r + b.r;
        if (d > 0.0001 && d < min) {
          const push = ((min - d) / d) * 0.36;
          dx *= push;
          dy *= push;
          a.x -= dx;
          a.y -= dy;
          b.x += dx;
          b.y += dy;
        }
      }
    }
  }

  killEnemy(e) {
    if (e.dead) return;
    e.dead = true;
    this.kills += 1;
    this.addScore(e.score);
    this.shake = Math.max(this.shake, e.type === 'hulk' ? 5 : 2.5);
    this.spawnParticles(e.x, e.y, e.color, e.type === 'hulk' ? 22 : 13, {
      speed: e.type === 'hulk' ? 85 : 60,
      life: 0.6,
      size: e.type === 'hulk' ? 2 : 1,
    });
    if (e.score >= 300) this.showText(`+${e.score}`, e.x, e.y - 6, e.color, 0.8);
    this.sfx.explode();
  }

  // ---------- humans / collision ----------

  updateHumans(dt) {
    const w = this.view.w;
    const h = this.view.h;
    for (const hm of this.humans) {
      if (hm.dead) continue;
      let near = null;
      let nd = Infinity;
      for (const e of this.enemies) {
        if (e.spawnT > 0 || e.dead) continue;
        const d = dist(hm.x, hm.y, e.x, e.y);
        if (d < nd) {
          nd = d;
          near = e;
        }
      }
      if (near && nd < 38) {
        const dx = hm.x - near.x;
        const dy = hm.y - near.y;
        const m = Math.hypot(dx, dy) || 1;
        hm.x += (dx / m) * 24 * dt;
        hm.y += (dy / m) * 24 * dt;
      } else {
        hm.wander -= dt;
        if (hm.wander <= 0) {
          hm.wander = rand(0.8, 2.6);
          const a = rand(0, Math.PI * 2);
          hm.dirX = Math.cos(a);
          hm.dirY = Math.sin(a);
        }
        hm.x += hm.dirX * 7 * dt;
        hm.y += hm.dirY * 7 * dt;
      }
      if (hm.x < 10 || hm.x > w - 10) hm.dirX *= -1;
      if (hm.y < 30 || hm.y > h - 10) hm.dirY *= -1;
      hm.x = clamp(hm.x, 10, w - 10);
      hm.y = clamp(hm.y, 30, h - 10);
    }
  }

  rescueHuman(hm, points, options = {}) {
    if (hm.dead) return;
    hm.dead = true;
    this.rescued += 1;
    this.rescuedThisWave += 1;
    this.addScore(points);
    this.spawnParticles(hm.x, hm.y, '#ffd23f', 10, { speed: 45, life: 0.5, size: 1 });
    this.spawnParticles(hm.x, hm.y, '#ffffff', 4, { speed: 30, life: 0.35, size: 1 });
    if (!options.silent) {
      this.showText(`+${points}`, hm.x, hm.y - 7, '#ffd23f', 0.9);
      this.sfx.rescue();
    }
  }

  killHuman(hm) {
    if (hm.dead) return;
    hm.dead = true;
    this.spawnParticles(hm.x, hm.y, '#ff5f7a', 12, { speed: 50, life: 0.55, size: 1 });
    this.spawnParticles(hm.x, hm.y, '#ffd23f', 5, { speed: 35, life: 0.4, size: 1 });
    this.sfx.hit();
  }

  collideBullets() {
    for (let i = this.bullets.length - 1; i >= 0; i--) {
      const b = this.bullets[i];
      if (b.dead) continue;
      for (const e of this.enemies) {
        if (e.dead || e.spawnT > 0) continue;
        if (dist(b.x, b.y, e.x, e.y) < b.r + e.r) {
          b.dead = true;
          e.hp -= 1;
          e.hitFlash = 0.09;
          this.spawnParticles(b.x, b.y, e.color, 3, { speed: 30, life: 0.25, size: 1 });
          this.sfx.hit();
          if (e.hp <= 0) this.killEnemy(e);
          break;
        }
      }
    }
    this.bullets = this.bullets.filter((b) => !b.dead);
  }

  collidePlayer() {
    const p = this.player;
    if (p.dead || p.invuln > 0) return;
    for (const e of this.enemies) {
      if (e.dead || e.spawnT > 0) continue;
      if (dist(p.x, p.y, e.x, e.y) < p.r + e.r) {
        this.playerDie();
        break;
      }
    }
  }

  collideHumans() {
    for (const hm of this.humans) {
      if (hm.dead) continue;
      for (const e of this.enemies) {
        if (e.dead || e.spawnT > 0) continue;
        if (dist(hm.x, hm.y, e.x, e.y) < hm.r + e.r) {
          this.killHuman(hm);
          break;
        }
      }
    }
  }

  clearWave() {
    this.waveState = 'clear';
    this.waveTimer = 0;
    let evac = 0;
    for (const hm of this.humans) {
      if (hm.dead) continue;
      evac += 1;
      this.rescueHuman(hm, 250, { silent: true });
    }
    if (evac) this.sfx.rescue();
    const bonus = 500 + this.wave * 100 + this.rescuedThisWave * 250;
    this.addScore(bonus);
    this.banner = {
      title: 'WAVE CLEAR',
      sub: `BONUS +${bonus}`,
      t: 0,
      life: 2.2,
      color: '#ffd23f',
    };
    this.shake = Math.max(this.shake, 2);
  }

  // ---------- particles ----------

  spawnParticles(x, y, color, count, opts = {}) {
    const speed = opts.speed || 50;
    const life = opts.life || 0.5;
    const size = opts.size || 1;
    for (let i = 0; i < count; i++) {
      const a = rand(0, Math.PI * 2);
      const s = rand(speed * 0.25, speed);
      this.particles.push({
        x,
        y,
        vx: Math.cos(a) * s,
        vy: Math.sin(a) * s,
        life: rand(life * 0.45, life),
        maxLife: life,
        color,
        size: Math.random() < 0.25 ? size + 1 : size,
      });
    }
    if (this.particles.length > 500) this.particles.splice(0, this.particles.length - 500);
  }

  // ---------- render ----------

  render() {
    renderGame(this, this.ctx);
  }
}

import { drawText, measureText, drawWrapped } from './font.js';
import { drawSprite, drawHumanIcon } from './sprites.js';

const pad = (n, width = 2) => String(Math.max(0, Math.floor(n))).padStart(width, '0');
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

const COL = {
  white: '#f2f7ff',
  dim: '#7f8fc0',
  faint: '#3f4d78',
  cyan: '#3df2ff',
  pink: '#ff3d8b',
  gold: '#ffd23f',
  green: '#7cffb2',
  red: '#ff3b57',
};

export function renderGame(g, ctx) {
  const { w, h } = g.view;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.imageSmoothingEnabled = false;
  ctx.globalAlpha = 1;
  ctx.fillStyle = '#05060d';
  ctx.fillRect(0, 0, w, h);

  drawBackground(g, ctx);

  if (g.state === 'title') {
    drawAmbient(g, ctx);
    drawTitle(g, ctx);
    drawButtons(g, ctx);
    return;
  }

  const shakeX = g.shake > 0.2 ? Math.round((Math.random() * 2 - 1) * g.shake) : 0;
  const shakeY = g.shake > 0.2 ? Math.round((Math.random() * 2 - 1) * g.shake) : 0;
  ctx.save();
  ctx.translate(shakeX, shakeY);
  drawWorld(g, ctx);
  ctx.restore();

  if (g.state === 'playing' || g.state === 'paused') {
    drawHud(g, ctx);
    drawBanner(g, ctx);
    if (g.state === 'playing') drawTouch(g, ctx);
  }

  if (g.state === 'paused') {
    drawPause(g, ctx);
    drawButtons(g, ctx);
  } else if (g.state === 'gameover') {
    drawGameOver(g, ctx);
    drawButtons(g, ctx);
  } else if (g.state === 'playing') {
    drawButtons(g, ctx);
  }
}

function drawBackground(g, ctx) {
  const { w, h } = g.view;

  // faint constellation floor
  for (const s of g.stars) {
    ctx.globalAlpha = s.a;
    ctx.fillStyle = s.c;
    ctx.fillRect(s.x, s.y, 1, 1);
  }
  ctx.globalAlpha = 1;

  const step = w < 300 ? 20 : 24;
  ctx.lineWidth = 1;
  ctx.strokeStyle = 'rgba(52, 88, 168, 0.13)';
  ctx.beginPath();
  for (let x = step; x < w; x += step) {
    ctx.moveTo(x + 0.5, 0);
    ctx.lineTo(x + 0.5, h);
  }
  for (let y = step; y < h; y += step) {
    ctx.moveTo(0, y + 0.5);
    ctx.lineTo(w, y + 0.5);
  }
  ctx.stroke();

  ctx.strokeStyle = 'rgba(31, 55, 112, 0.8)';
  ctx.lineWidth = 2;
  ctx.strokeRect(1, 1, w - 2, h - 2);
  ctx.strokeStyle = 'rgba(61, 242, 255, 0.16)';
  ctx.lineWidth = 1;
  ctx.strokeRect(4.5, 4.5, w - 9, h - 9);

  // corner brackets
  const L = 10;
  const corners = [
    [4, 4, 1, 1, COL.cyan],
    [w - 5, 4, -1, 1, COL.pink],
    [4, h - 5, 1, -1, COL.pink],
    [w - 5, h - 5, -1, -1, COL.cyan],
  ];
  ctx.lineWidth = 2;
  for (const [x, y, sx, sy, color] of corners) {
    ctx.strokeStyle = color;
    ctx.globalAlpha = 0.5;
    ctx.beginPath();
    ctx.moveTo(x, y + sy * L);
    ctx.lineTo(x, y);
    ctx.lineTo(x + sx * L, y);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
}

function drawAmbient(g, ctx) {
  const art = g.view.art;
  for (const a of g.ambient) {
    const bob = Math.sin(a.phase * 1.8) * 1.5;
    ctx.globalAlpha = 0.32;
    drawSprite(ctx, a.type, a.x, a.y + bob, art, false, 1);
  }
  ctx.globalAlpha = 1;
}

function drawWorld(g, ctx) {
  const art = g.view.art;
  const t = g.time;

  for (const hm of g.humans) {
    if (hm.dead) continue;
    const bob = Math.sin(t * 4 + hm.seed) * 0.6;
    ctx.globalAlpha = 0.28;
    ctx.fillStyle = '#000000';
    ctx.fillRect(Math.round(hm.x - 3), Math.round(hm.y + 5), 6, 2);
    ctx.globalAlpha = 1;
    drawSprite(ctx, 'human', hm.x, hm.y + bob, art);
  }

  for (const e of g.enemies) {
    if (e.spawnT > 0) {
      drawSpawnRing(g, ctx, e);
      continue;
    }
    const bob = e.type === 'spheroid' || e.type === 'brain' ? Math.sin(t * 5 + e.seed) * 1.1 : 0;
    ctx.globalAlpha = 0.3;
    ctx.fillStyle = '#000000';
    ctx.fillRect(Math.round(e.x - e.r), Math.round(e.y + e.r * 0.75), Math.round(e.r * 2), 2);
    ctx.globalAlpha = 1;

    if (e.type === 'spheroid' || e.type === 'brain') {
      ctx.globalAlpha = 0.13;
      ctx.fillStyle = e.color;
      ctx.beginPath();
      ctx.arc(Math.round(e.x), Math.round(e.y + bob), e.r + 4, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
    }

    drawSprite(ctx, e.type, e.x, e.y + bob, art, e.hitFlash > 0);

    if (e.type === 'hulk' && e.hp < e.maxHp) {
      const width = Math.round(e.r * 2);
      const x = Math.round(e.x - e.r);
      const y = Math.round(e.y - e.r - 6);
      ctx.fillStyle = 'rgba(0,0,0,0.55)';
      ctx.fillRect(x - 1, y - 1, width + 2, 3);
      ctx.fillStyle = COL.red;
      ctx.fillRect(x, y, Math.max(0, Math.round((width * e.hp) / e.maxHp)), 1);
    }
  }

  // bullets
  for (const b of g.bullets) {
    ctx.globalAlpha = 0.28;
    ctx.fillStyle = COL.cyan;
    ctx.fillRect(Math.round(b.x - b.vx * 0.018) - 1, Math.round(b.y - b.vy * 0.018) - 1, 3, 3);
    ctx.globalAlpha = 1;
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(Math.round(b.x) - 1, Math.round(b.y) - 1, 2, 2);
  }

  drawPlayer(g, ctx, art);

  // particles
  for (const p of g.particles) {
    const a = clamp(p.life / p.maxLife, 0, 1);
    ctx.globalAlpha = a;
    ctx.fillStyle = p.color;
    const s = Math.max(1, Math.round(p.size * (0.6 + a * 0.4)));
    ctx.fillRect(Math.round(p.x), Math.round(p.y), s, s);
  }
  ctx.globalAlpha = 1;

  for (const txt of g.texts) {
    const a = clamp(txt.life / txt.maxLife, 0, 1);
    ctx.globalAlpha = a;
    drawText(ctx, txt.text, txt.x, txt.y, 1, txt.color, 'center', 'rgba(0,0,0,0.7)');
  }
  ctx.globalAlpha = 1;
}

function drawSpawnRing(g, ctx, e) {
  const p = 1 - e.spawnT / 0.6;
  const r = e.r + 3 + Math.sin(g.time * 24 + e.seed) * 1.2;
  ctx.globalAlpha = 0.35 + Math.sin(g.time * 18 + e.seed) * 0.2;
  ctx.strokeStyle = e.color;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(Math.round(e.x), Math.round(e.y), Math.max(2, r), 0, Math.PI * 2);
  ctx.stroke();
  ctx.globalAlpha = 0.18 + p * 0.25;
  drawSprite(ctx, e.type, e.x, e.y, g.view.art, false);
  ctx.globalAlpha = 1;
}

function drawPlayer(g, ctx, art) {
  const p = g.player;
  if (p.dead) return;
  const blink = p.invuln > 0 && Math.floor(g.time * 18) % 2 === 0;
  if (blink) return;

  ctx.globalAlpha = 0.32;
  ctx.fillStyle = '#000000';
  ctx.fillRect(Math.round(p.x - 4), Math.round(p.y + 4), 8, 2);
  ctx.globalAlpha = 1;

  // gun / aim line
  const ax = p.aimX;
  const ay = p.aimY;
  ctx.strokeStyle = 'rgba(61, 242, 255, 0.55)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(Math.round(p.x + ax * 4), Math.round(p.y + ay * 4));
  ctx.lineTo(Math.round(p.x + ax * 9), Math.round(p.y + ay * 9));
  ctx.stroke();

  if (p.muzzle > 0) {
    const mx = Math.round(p.x + ax * 10);
    const my = Math.round(p.y + ay * 10);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(mx - 1, my - 1, 2, 2);
    ctx.fillStyle = COL.cyan;
    ctx.fillRect(Math.round(p.x + ax * 8), Math.round(p.y + ay * 8), 1, 1);
  }

  drawSprite(ctx, 'player', p.x, p.y, art);

  if (p.invuln > 0) {
    ctx.globalAlpha = 0.4 + Math.sin(g.time * 12) * 0.2;
    ctx.strokeStyle = COL.cyan;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(Math.round(p.x), Math.round(p.y), 8, 0, Math.PI * 2);
    ctx.stroke();
    ctx.globalAlpha = 1;
  }
}

