edgeSpawn() {
  const w = this.view.w;
  const h = this.view.h;
  const m = 10;
  const minD = Math.min(75, Math.min(w, h) * 0.3);
  let pick = { x: m, y: m };
  let best = -1;
  for (let i = 0; i < 14; i++) {
    const side = Math.floor(Math.random() * 4);
    let x;
    let y;
    if (side === 0) {
      x = rand(m, w - m);
      y = m;
    } else if (side === 1) {
      x = w - m;
      y = rand(m, h - m);
    } else if (side === 2) {
      x = rand(m, w - m);
      y = h - m;
    } else {
      x = m;
      y = rand(m, h - m);
    }
    const d = dist(x, y, this.player.x, this.player.y);
    if (d > best) {
      best = d;
      pick = { x, y };
    }
    if (d > minD) break;
  }
  return pick;
}

